mapper.select:
SELECT aa.ID, aa.ACCOUNT_KEY, aa.ACCOUNT_NAME, aa.PROVIDER, aa.API_URL, aa.ACCOUNT_TOKENS, aa.ENV_CODE, aa.DELETED, aa.CREATE_USER, aa.CREATE_TIME, ( SELECT COUNT(1) FROM `AI_MODEL` am WHERE (am.DELETED = 0 OR am.DELETED IS NULL) AND am.ACCOUNT_KEY = aa.ACCOUNT_KEY AND am.ENV_CODE = aa.ENV_CODE ) AS usedModelCount, ( SELECT GROUP_CONCAT(DISTINCT am.MODEL_KEY ORDER BY am.MODEL_KEY SEPARATOR ',') FROM `AI_MODEL` am WHERE (am.DELETED = 0 OR am.DELETED IS NULL) AND am.ACCOUNT_KEY = aa.ACCOUNT_KEY AND am.ENV_CODE = aa.ENV_CODE ) AS usedModelKeys, ( SELECT GROUP_CONCAT(DISTINCT am.MODEL_NAME ORDER BY am.MODEL_NAME SEPARATOR ',') FROM `AI_MODEL` am WHERE (am.DELETED = 0 OR am.DELETED IS NULL) AND am.ACCOUNT_KEY = aa.ACCOUNT_KEY AND am.ENV_CODE = aa.ENV_CODE ) AS usedModelNames FROM `AI_ACCOUNT` aa WHERE (aa.DELETED = 0 OR aa.DELETED IS NULL)
AND aa.ACCOUNT_KEY LIKE CONCAT('%', #{req.accountKey}, '%')
AND aa.ACCOUNT_NAME LIKE CONCAT('%', #{req.accountName}, '%')
AND aa.PROVIDER = #{req.provider}
AND aa.ENV_CODE = #{req.envCode}
AND aa.CREATE_USER = #{req.createUser}
ORDER BY aa.CREATE_TIME DESC
